<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import PageHeading from '../components/common/PageHeading.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import MetricChart from '../components/charts/MetricChart.vue'
import {useDemoStore} from '../stores/demo'
import {formatTime} from '../mocks/catalog'
import {download} from '../utils/download'
const route=useRoute(),router=useRouter(),store=useDemoStore()
const job=computed(()=>store.jobs.find(j=>j.id===route.params.id))
const history=computed(()=>store.lossHistories.find(h=>h.jobId===job.value?.id)?.points??[])
const autoScroll=ref(true),lastClearedLog=ref<string|null>(null),terminal=ref<HTMLElement>()
watch(()=>route.params.id,()=>{lastClearedLog.value=null})
const logs=computed(()=>{const all=job.value?.logs??[];return lastClearedLog.value===null?all:all.slice(all.lastIndexOf(lastClearedLog.value)+1)})
watch(()=>job.value?.logs?.join('\n'),async()=>{await nextTick();if(autoScroll.value&&terminal.value)terminal.value.scrollTop=terminal.value.scrollHeight},{immediate:true})
function toggleScroll(){autoScroll.value=!autoScroll.value;if(autoScroll.value&&terminal.value)terminal.value.scrollTop=terminal.value.scrollHeight}
const cps=computed(()=>store.checkpoints.filter(cp=>cp.job===job.value?.id))
const speed=computed(()=>Math.max(100,Math.ceil((job.value?.config?.steps??50000)/200))/2)
const metrics=computed(()=>job.value?[['Global Step',job.value.step.toLocaleString()],['Total Steps',(job.value.config?.steps??50000).toLocaleString()],['Epoch（估算）',store.datasets.find(d=>d.name===job.value?.dataset)?.episodes?(job.value.step*(job.value.config?.batchSize??16)/store.datasets.find(d=>d.name===job.value?.dataset)!.episodes).toFixed(2):'—'],['Training Loss',job.value.loss.toFixed(4)],['Learning Rate',(job.value.metrics?.at(-1)?.lr??job.value.config?.learningRate??0).toExponential(2)],['Steps/s（模拟）',job.value.status==='Running'?speed.value.toFixed(1):'—'],['运行时长',formatTime(job.value.elapsed)],['预计剩余',job.value.status==='Running'?formatTime(((job.value.config?.steps??50000)-job.value.step)/speed.value):'—']]:[])
function chart(data:number[][],name:string,color:string,max?:number){const text=store.dark?'#91a0b6':'#8792a5',grid=store.dark?'#273347':'#eef1f6';return {animationDuration:200,grid:{top:25,left:50,right:15,bottom:30},tooltip:{trigger:'axis',renderMode:'richText'},xAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{show:false}},yAxis:{type:'value',max,axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:grid,type:'dashed'}}},series:[{name,type:'line',showSymbol:false,lineStyle:{width:2},itemStyle:{color},areaStyle:{opacity:.05},data}]}}
const charts=computed(()=>[{name:'Training Loss',option:chart(history.value.map(p=>[p.step,p.loss]),'Loss','#3974f6')},{name:'Learning Rate',option:chart(job.value?.metrics?.map(p=>[p.step,p.lr])??[],'Learning Rate','#8b74d4')},{name:'GPU 利用率 · %',option:chart(job.value?.metrics?.map(p=>[p.step,p.utilization])??[],'GPU %','#39b6a0',100)},{name:'GPU 显存 · GB',option:chart(job.value?.metrics?.map(p=>[p.step,p.memory])??[],'GPU GB','#d6a24c',80)}])
function exportLogs(){download(`${job.value?.id}-mock.log`,(job.value?.logs??[]).join('\n'));store.notify('已下载完整模拟日志。')}
</script>
<template><template v-if="job"><PageHeading :title="job.name" description="任务监控 · 实时模拟训练指标与日志"><button class="button" @click="router.push('/jobs')">返回任务</button><button v-if="['Running','Pending'].includes(job.status)" class="button danger" @click="store.stop(job.id)">停止任务</button><button class="button" @click="store.live=!store.live">{{store.live?'暂停模拟时钟':'恢复模拟时钟'}}</button></PageHeading><div class="monitor-meta"><StatusBadge :status="job.status"/><span>{{job.id}}</span><span>{{job.model}}</span><span>{{job.dataset}}</span><span>启动于 {{job.started}}</span><span>{{job.gpu}}</span></div><div class="monitor-progress"><div :style="{width:job.progress+'%'}"></div></div><div v-if="!store.live" class="info-note">模拟时钟已暂停，所有任务的指标暂停更新。</div><div class="stat-strip"><div v-for="item in metrics" :key="item[0]" class="strip-item"><span>{{item[0]}}</span><strong>{{item[1]}}</strong></div></div><div class="monitor-charts"><section v-for="c in charts" :key="c.name" class="panel monitor-chart"><h2>{{c.name}}</h2><MetricChart :option="c.option"/></section></div><section class="panel"><div class="log-head"><h2>训练日志 <span class="small-badge">MOCK</span></h2><div class="log-actions"><button class="text-link" @click="toggleScroll">{{autoScroll?'暂停自动滚动':'恢复自动滚动'}}</button><button class="text-link" @click="lastClearedLog=job.logs?.at(-1)??null">清空视图</button><button class="text-link" @click="lastClearedLog=null">显示全部</button><button class="text-link" @click="exportLogs">下载日志</button></div></div><pre ref="terminal" class="log-terminal" aria-label="模拟训练日志">{{logs.length?logs.join('\n'):'日志视图已清空，等待新日志。'}}</pre></section><section class="panel content-panel" style="margin-top:22px"><div class="section-intro"><div><h2>本任务 Checkpoints</h2><button class="text-link" @click="router.push({path:'/checkpoints',query:{job:job.id}})">进入管理 →</button></div><p>按保存间隔自动记录模拟快照，只有元数据，不包含权重。</p></div><div v-if="!cps.length" class="info-note">尚未到达保存间隔。</div><div v-for="cp in cps.slice(0,4)" :key="cp.name" class="setting-row"><span>{{cp.name}}<small>Step {{cp.step.toLocaleString()}} · {{cp.created}}</small></span><button class="text-link" @click="router.push({path:'/training',query:{resume:cp.name}})">模拟 Resume</button></div></section><details class="info-note"><summary>模拟故障与配置详情</summary><button class="button danger" style="margin:12px 0" :disabled="!['Running','Pending'].includes(job.status)" @click="store.fail(job.id)">模拟 GPU 显存不足</button><pre class="command-preview">{{JSON.stringify(job.config,null,2)}}</pre><p>Epoch 根据 episode 数量估算；GPU 图为模拟设备指标，未读取真实硬件。</p></details></template><section v-else class="panel empty-state">未找到此任务，可能已重置演示。<br><button class="button primary" @click="router.push('/jobs')">返回训练任务</button></section></template>
